var t=[{title:`Das Verhältnis lesen`,text:`Ein 1:3-Intervall könnte 20 Sekunden Belastung und 60 Sekunden Erholung sein, ein 1:1-Intervall je 30 Sekunden von beidem und 2:1 könnte 40 Sekunden Arbeit und 20 Sekunden leicht sein. Das Verhältnis allein beschreibt das Training nicht, bis du Dauer und Intensität kennst.`},{title:`Lange Erholung für Qualität`,text:`Recht lange Pausen helfen dir, Tempo oder Leistung über kurze harte Belastungen zu halten. Ein 1:3-Aufbau kann zu jemandem passen, der schnelleres Laufen oder eine anspruchsvolle Bewegung übt und nicht sofort ermüden will. Sehr intensives Sprinten kann weit mehr Erholung als 1:3 brauchen, um die Leistung hochzuhalten.`},{title:`Gleiche oder kurze Erholung`,text:`Bei 1:1 dauern Arbeit und Erholung gleich lang. Bei 2:1 ist die Erholung kürzer, sodass sich Ermüdung schnell aufbauen kann. Diese Formate können für moderate Zirkel funktionieren, sind aber für fortgeschrittene Ausdauer- oder Kraftziele nicht automatisch besser.`},{title:`An Fähigkeit und Übung anpassen`,text:`Ein Anfänger könnte 30 Sekunden zügig und 90 Sekunden leicht gehen und dann die Arbeit langsam verlängern. Ein trainierter Radfahrer nutzt vielleicht längere harte Belastungen mit großzügiger Erholung. Sprungbewegungen brauchen oft mehr technische Kontrolle, wähle also eine Pause, die deine Landungen gut hält. Beurteile den Fortschritt danach, ob du mit guter Technik fertig wirst, verlängere die Pause, wenn du sie brauchst, und mache nicht jedes Intervall härter, nur um das Training zu verkürzen.`}];var i=[{label:`ACE: Hochintensive Intervalle gestalten`,url:`https://www.acefitness.org/continuing-education/certified/may-2021/7844/how-to-use-the-ace-ift-model-to-design-effective-hiit-workouts/`},{label:`CDC: Intensität der Aktivität messen und Sprechtest`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`CDC: Empfehlungen zur körperlichen Aktivität für Erwachsene`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var r={sections:t,sources:i};export{r as default,t as sections,i as sources};